use std::collections::{HashMap,HashSet};impl Solution{pub fn word_pattern_match(p:String,s:String)->bool{fn f(p:&[u8],i:usize,s:&str,j:usize,m:&mut HashMap<u8,String>,u:&mut HashSet<String>)->bool{if i==p.len()||j==s.len(){return i==p.len()&&j==s.len()}let c=p[i];if let Some(x)=m.get(&c).cloned(){return s[j..].starts_with(&x)&&f(p,i+1,s,j+x.len(),m,u)}for e in j+1..=s.len(){let x=s[j..e].to_string();if u.contains(&x){continue}m.insert(c,x.clone());u.insert(x.clone());if f(p,i+1,s,e,m,u){return true}u.remove(&x);m.remove(&c);}false}f(p.as_bytes(),0,&s,0,&mut HashMap::new(),&mut HashSet::new())}}
